(()=>{const path=location.pathname.replace(/\/$/,'')||'/';const pages={'/iptv-reseller-guide':['IPTV Reseller Guide: Panels, Credits & Setup','Learn how to choose IPTV reseller panels, plan credits and prepare a compliant customer onboarding workflow.','IPTV reseller guide','A practical guide to choosing the right panel, comparing regional coverage and planning credit durations.','How to choose a reseller panel','Start with the audience geography, devices your customers use, catalog requirements and the credit-duration model. Confirm live availability before purchasing.'], '/m3u-vs-xtream':['M3U vs Xtream Codes API: IPTV Setup Guide','Compare M3U playlists and Xtream Codes API credentials for supported IPTV app setup workflows.','M3U Playlist vs Xtream Codes API','Both are common authorized setup formats for IPTV applications.','What is an M3U playlist?','An M3U playlist is a portable media list format. Xtream-style logins commonly use a server URL, username and password. Use only details supplied through an authorized order.'], '/iptv-reseller-credit-guide':['IPTV Reseller Credit Guide: Duration & Planning','Understand IPTV reseller credit duration systems and how to plan annual customer packages.','IPTV reseller credit-duration guide','Use panel-specific credit tables instead of assuming one conversion works everywhere.','How do reseller credits work?','A supplier defines how credits map to an end-user duration. Compare each server’s published table, then confirm current terms with sales.']};if(!pages[path])return;let [title,desc,eyebrow,lead,h2,text]=pages[path];document.title=title+' | iptvsreseller.net';document.getElementById('app').innerHTML=`<header class="wrap nav"><a class="brand" href="/"><span style="color:#67e8f9">iptv</span>sreseller.net</a><nav class="navlinks"><a href="/">Panels</a><a href="/compare/">Compare</a><a href="/apps-setup/">Setup</a><a href="/contact/">Contact</a></nav></header><main class="wrap article"><div class="crumb"><a href="/">Home</a> / ${eyebrow}</div><div class="eyebrow">SEO knowledge hub</div><h1>${title}</h1><p class="lead">${lead}</p><h2>${h2}</h2><p>${text}</p><h2>Next step for resellers</h2><p>Use the panel catalog to compare current coverage, catalog snapshots and the panel-specific credit system. For test-line availability, request an M3U/Xtream end-user trial—not a reseller panel demo.</p><a class="btn green" href="https://wa.me/212670779271?text=Hello,%20I%20need%20IPTV%20reseller%20information." target="_blank">Ask reseller support</a></main><footer class="footer"><div class="wrap">iptvsreseller.net · B2B reseller information · support@reselleriptv.com</div></footer>`})();
